// String prints human readable information.
func (tp Protocol) String() string {
	// Handle known single protocols and common composites first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	}

	// Handle composite protocols by iterating through bits
	var names []string
	allFlags := []struct {
		flag Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	for _, f := range allFlags {
		if tp&f.flag != 0 {
			names = append(names, f.name)
		}
	}

	if len(names) > 0 {
		result := names[0]
		for i := 1; i < len(names); i++ {
			result += "|" + names[i]
		}
		return result
	}

	return Unknown
}

