// Dump returns diagnostic information about the connection pool state.
// It provides visibility into pool size, active connections, and addresses.
// This is useful for debugging connection issues and monitoring pool health.
func (p *connPool) Dump() interface{} {
	type connInfo struct {
		Address       string
		PoolSize      uint32
		Connections   int
		ActiveCount   int
		CurrentIndex  uint32
	}

	var dumps []connInfo
	p.conns.Range(func(key, value interface{}) bool {
		address := key.(string)
		trans := value.(*transports)

		activeCount := 0
		connCount := 0
		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] != nil {
				connCount++
				if trans.cliTransports[i].(grpc.IsActive).IsActive() {
					activeCount++
				}
			}
		}

		dumps = append(dumps, connInfo{
			Address:      address,
			PoolSize:     trans.size,
			Connections:  connCount,
			ActiveCount:  activeCount,
			CurrentIndex: atomic.LoadUint32(&trans.index),
		})
		return true
	})

	return map[string]interface{}{
		"remote_service": p.remoteService,
		"pool_size":      p.size,
		"short_conn":     p.connOpts.ShortConn,
		"connections":    dumps,
	}
}

