// readAndCheckFrameHeader reads a frame header from the underlying reader
// and performs basic validation. Returns enhanced error diagnostics including
// hex dump of the first 8 bytes when frame validation fails.
func (fr *Framer) readAndCheckFrameHeader() (http2.FrameHeader, error) {
	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	// Parse frame header
	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Basic validation - if frame looks invalid, provide diagnostic info
	if fh.Length > fr.maxReadSize {
		// Read next 4 bytes for better diagnostics if available
		var second4Bytes uint32
		if extraBuf, err := fr.reader.Next(4); err == nil {
			second4Bytes = binary.BigEndian.Uint32(extraBuf)
		}
		first4Bytes := binary.BigEndian.Uint32(buf[0:4])

		return http2.FrameHeader{}, fr.connError(http2.ErrCodeFrameSize,
			fmt.Sprintf("invalid frame (first4Bytes=%#x, second4Bytes=%#x): frame too large (%d > %d)",
				first4Bytes, second4Bytes, fh.Length, fr.maxReadSize))
	}

	return fh, nil
}

